<?php
define('PAGE_TITLE','Completed Question Banks');
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/system.php';require_once __DIR__.'/../../includes/workflow.php';
requireAuth();$pdo=getDBConnection();$user=getCurrentUser();if(empty($_SESSION['qps_static_role']))$_SESSION['qps_portal_role']='STAFF';
if(!in_array(qps_workflow_role(),['STAFF','HOD','DEAN'],true)){http_response_code(403);exit('Teaching portal access denied.');}
$st=$pdo->prepare("SELECT p.*,d.course_title,d.course_type,d.max_marks,d.dept_name FROM qps_submission_packages p LEFT JOIN qps_question_bank_drafts d ON d.id=p.bank_draft_id WHERE p.staff_code=? AND p.status IN ('SUBMITTED_TO_COE','COE_APPROVED','ALLOTTED','PAPER_GENERATED') ORDER BY p.updated_at DESC");$st->execute([$user['staff_code']]);$rows=$st->fetchAll(PDO::FETCH_ASSOC);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/navbar.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="max-w-7xl mx-auto px-4 py-6 space-y-5"><div><h1 class="text-3xl font-black">My Assigned Course Banks</h1><p class="text-sm text-slate-500">Courses approved by the Dean and forwarded to COE. Draft data is retained until COE approval.</p></div>
<div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($rows as $r):?><article class="bg-white border rounded-2xl p-5 shadow-sm"><h2 class="text-2xl font-black"><?=htmlspecialchars($r['paper_code'])?></h2><p class="text-sm font-semibold text-slate-700"><?=htmlspecialchars($r['course_title']??'')?></p><div class="flex flex-wrap gap-2 mt-3"><span class="rounded-full bg-indigo-50 text-indigo-700 px-3 py-1 text-xs font-black"><?=htmlspecialchars($r['course_type']??'Course')?></span><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-black"><?=htmlspecialchars((string)($r['max_marks']??''))?> Marks</span><span class="rounded-full bg-emerald-100 text-emerald-800 px-3 py-1 text-xs font-black"><?=htmlspecialchars($r['status'])?></span></div><div class="flex flex-wrap gap-2 mt-4"><a class="rounded-lg bg-slate-100 px-3 py-2 text-xs font-bold" href="view_banks.php?draft_id=<?=(int)$r['bank_draft_id']?>">View Question Bank</a><a class="rounded-lg bg-slate-100 px-3 py-2 text-xs font-bold" href="question_bank_blueprint.php?paper_code=<?=rawurlencode($r['paper_code'])?>">View Question Bank Blueprint</a><a class="rounded-lg bg-slate-100 px-3 py-2 text-xs font-bold" href="final_slot_allocation.php?paper_code=<?=rawurlencode($r['paper_code'])?>">View Final Blueprint</a></div></article><?php endforeach;?></div>
<?php if(!$rows):?><div class="border border-dashed rounded-2xl p-10 text-center text-slate-500">No Dean-approved course banks yet.</div><?php endif;?></main>
